#include <algorithm>   // std::ranges::fold_left (C++23)
#include <ranges>

long factorial(int n) {
    auto nums = std::views::iota(1, n + 1);   // unfold, lazily; no container
    return std::ranges::fold_left(            // fold in the same pass
        nums, 1L, [](long acc, int v) { return acc * v; });
}
