template <class State, class Acc, class Coalg, class Alg>
Acc hylo(State s, Acc acc, Coalg coalg, Alg alg) {
    while (auto layer = coalg(s)) {          // unfold one layer
        acc = alg(acc, layer->first);        // fold it immediately
        s = layer->second;                   // advance the seed
    }
    return acc;
}
// coalg: State -> std::optional<std::pair<Value, State>>,  alg: (Acc, Value) -> Acc
